var sv = SugarCube.State.variables;
sv.player.flagBag = sv.player.flagBag || {};
sv.player.core_traits.npc_frank_stage = 4;
sv.player.flagBag.frank_invited_to_bedroom = true;
sv.player.flagBag.frank_bedroom_first_done = false;
sv.player.flagBag.talked_to_frank_today = false;
sv.player.core_traits.corruption = 10;  // BELOW gate (25) — triggers locked sibling
var frankUuid = null;
for (var k in sv.npcs) { if (sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; } }
if (frankUuid) sv.npcs[frankUuid].core_traits.arousal = 0;
SugarCube.Engine.play('Canvas_scene_franks_bedroom_evening_Node_1');
'set'

var sv = SugarCube.State.variables;
// Set Frank Stage 3 + partial gate state so we can see the counter badges in 'almost-met' form
sv.player.core_traits.npc_frank_stage = 3;
sv.player.core_traits.corruption = 35;  // 35/50 (player corruption gate)
sv.player.flagBag = sv.player.flagBag || {};
sv.player.flagBag.frank_restrict_declared = true;  // flag met
sv.player.flagBag.frank_offered_bookkeeping = true;  // flag met
var frankUuid = null;
for (var k in sv.npcs) { if (sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; } }
if (frankUuid) {
  sv.npcs[frankUuid].core_traits.arousal = 18;     // 18/30
  sv.npcs[frankUuid].core_traits.corruption = 12;  // 12/15
  sv.npcs[frankUuid].core_traits.trust = 10;       // 10/10 met
}
'set'
